// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address caller, uint256 val) public {
        if(caller == address(0)) caller = address(1);
        uint256 v = bound(val, 1, type(uint256).max);

        bool ok1;
        try c.SetMinSum(v) { ok1 = true; } catch { ok1 = false; }
        vm.assume(ok1);

        bool ok2;
        vm.prank(caller);
        try c.SetMinSum(v + 1) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok2);
    }
}
